request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
binary-016

Cluster Arity:
2

Cluster Members:
[
  {
    "name": "LOCATES_TARGET_WITHIN_OBSERVED_STRUCTURE",
    "definition": "The reasoning identifies a specific element within a structure, history, or set of records described by an observation as the location, container, or source of a target of interest.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node pinpointing a specific locus of the target within the observed structure."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation describing the structure, history, or set of records being searched."
      }
    ],
    "assertion_conditions": [
      "The observation describes a structure, history, or set of records with identifiable individual elements.",
      "The reasoning points to at least one specific element within that observed structure as containing, retaining, or being associated with the target of interest."
    ],
    "exclusion_conditions": [
      "The reasoning only summarizes the observed structure without singling out any element.",
      "The reasoning states a target value without relating it to a location or record visible in the observation.",
      "The observation does not contain the structure or records being localized."
    ]
  },
  {
    "name": "GUIDES_NEXT_INVESTIGATION_BY_OBSERVED_FEATURE",
    "definition": "The reasoning uses a specific feature reported in an observation as the basis for selecting the next investigative target or action.",
    "parameters": [
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation reporting a feature, artifact, directory, file listing, size, or result that can motivate further investigation."
      },
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The reasoning node that references the observed feature and formulates the next investigative step from it."
      }
    ],
    "assertion_conditions": [
      "The observation reports an identifiable feature, such as a discovered directory, file, size, content pattern, or occurrence.",
      "The reasoning explicitly refers to or relies on that feature when selecting what to investigate or do next.",
      "The next investigative step is connected to the observed feature rather than being unrelated background activity."
    ],
    "exclusion_conditions": [
      "The reasoning merely repeats the observation without deriving or selecting a next investigative step.",
      "The next step is unrelated to any feature reported in the observation.",
      "The observation contains no identifiable feature that the reasoning uses for guidance.",
      "The reasoning plans a next step from prior knowledge or a general obligation without citing any feature of the observation."
    ]
  },
  {
    "name": "REFINES_DETECTION_CRITERIA_FROM_OBSERVATION",
    "definition": "The reasoning modifies or narrows a search or detection strategy in response to an earlier observation indicating that the prior strategy produced noise, false positives, truncation, or otherwise inadequate results.",
    "parameters": [
      {
        "name": "refined_reasoning",
        "type": "reasoning",
        "description": "The reasoning node stating revised search or detection criteria."
      },
      {
        "name": "prior_observation",
        "type": "observation",
        "description": "The earlier observation whose noise, false positives, truncation, or inadequacy motivates the revision."
      }
    ],
    "assertion_conditions": [
      "The reasoning refers to the prior observation as noisy, overly broad, truncated, or otherwise insufficient for identifying the target instances.",
      "The reasoning proposes more specific, different, or otherwise adjusted search or detection criteria."
    ],
    "exclusion_conditions": [
      "The reasoning does not reference the prior observation as a basis for changing the search or detection strategy.",
      "The reasoning merely repeats the same criteria without adjustment."
    ]
  }
]

