["CONFIGURES_EVENT_DRIVEN_AUTOMATION", "PREVENTS_SELF_CAUSED_ADVERSE_EFFECTS_THROUGH_CORRECTIVE_ACTION", "EVALUATES_CANDIDATE_AGAINST_ENUMERATED_CONSTRAINTS_OR_SCENARIOS", "RESOLVES_EVALUATED_CANDIDATE_ELEMENTS_TO_SINGLE_RESULT", "INTERPRETS_REQUIREMENTS_FOR_ACTION_ADMISSIBILITY", "INITIATES_DETACHED_ASYNCHRONOUS_EXECUTION", "REPORTS_ABSENT_OR_UNAVAILABLE_CAPABILITY", "IDENTIFIES_SPECIFIC_POTENTIAL_FAILURE_MODE", "ASSESSES_COMPETING_ACCOUNTS_OF_SAME_OBSERVATION", "ESTABLISHES_EVIDENCE_GROUNDED_TASK_OUTCOME_REFERENCE", "FORMULATES_STRUCTURED_OPERATIVE_ACCOUNT", "SPECIFIES_TARGET_LINKED_CONCRETE_MEANS", "GROUNDS_COMPUTATIONAL_ASSESSMENT_IN_QUANTITATIVE_ANALYSIS", "ANTICIPATES_PROSPECTIVE_VERIFICATION", "DELIMITS_MODIFICATION_AND_RESIDUAL_ARTIFACT_SCOPE", "IDENTIFIES_DEFICIENCY_OR_INCOMPLETENESS", "REPRODUCES_SPECIFIED_PROCEDURE_OR_OPERATION_ORDER", "IMPLEMENTS_LIMITATION_RESPONSIVE_ALTERNATIVE_APPROACH", "EXECUTES_REASONED_REMOVAL_OF_UNWANTED_STATE", "RESOLVES_CANDIDATE_STATUS_FROM_OBSERVED_EVIDENCE", "GROUNDS_REASONING_SPECIFICATION_IN_OBSERVED_ACTION_OR_STATE", "MATERIALIZES_SPECIFIED_CONTENT_IN_DESIGNATED_ARTIFACT", "INTERPRETS_PROBLEMATIC_OBSERVATION_FOR_UNDERSTANDING_OR_RESPONSE", "GROUNDS_CONSTRAINT_OR_JUDGMENT_IN_OBSERVED_EVIDENCE", "CONFIRMS_INTENDED_EFFECT_OR_REQUIRED_STATE_FROM_OBSERVED_RESULT", "PRESERVES_VERIFIED_SUBSTANCE_DURING_REPRESENTATIONAL_REVISION", "CONSTRAINT_DRIVEN_ARTIFACT_ELIMINATION_OR_REVISION", "GENERALIZES_INFERRED_RULE_BEYOND_OBSERVED_EXAMPLES", "RECONSTRUCTS_ANCESTRY_OR_DIVERGENCE_FROM_VERSION_IDENTIFIERS", "INTEGRATES_MULTIPLE_OBSERVATIONS_INTO_UNIFIED_REPRESENTATION"]

Read every member's complete definition, ordered parameters, assertion conditions, and exclusion conditions. Identify the common underlying behavioral mechanism and generate exactly one complete predicate following the system instructions. The new predicate must preserve the cluster arity. Use a unique predicate name that does not conflict with previously generated predicate names. Return only the complete five-field JSON predicate.

message.content:
{
  "name": "DIRECTS_INVESTIGATIVE_FOCUS_FROM_OBSERVED_FEATURE",
  "definition": "The reasoning uses one or more specific, identifiable elements, features, records, structures, results, or reported inadequacies in an observation to identify a target locus, select a next investigative target or action, or revise search or detection criteria, so that subsequent inquiry is focused or adjusted on the basis of what was observed.",
  "parameters": [
    {
      "name": "reasoning",
      "type": "reasoning",
      "description": "The reasoning node that interprets the observation to pinpoint a target locus, select a next investigative step, or refine search or detection criteria."
    },
    {
      "name": "observation",
      "type": "observation",
      "description": "The observation reporting the structure, record set, feature, artifact, result, or inadequacy from which the reasoning draws its investigative focus or adjustment."
    }
  ],
  "assertion_conditions": [
    "The observation reports at least one identifiable feature, element, record, structure, result, or inadequacy that can serve as a basis for further inquiry.",
    "The reasoning explicitly references or relies on that observed feature, element, record, structure, result, or inadequacy.",
    "The reasoning uses it to single out a target location, source, or container, select a next investigative target or action, or propose revised search or detection criteria.",
    "The selected target, next step, or revised criteria is connected to the observed feature rather than being unrelated background activity."
  ],
  "exclusion_conditions": [
    "The reasoning merely repeats or summarizes the observation without deriving a focused target, next investigative step, or revised search or detection criteria.",
    "The selected target, next step, or revised criteria is unrelated to any feature reported in the observation or is based only on prior knowledge or a general obligation.",
    "The observation contains no identifiable feature, structure, record, result, or inadequacy that the reasoning uses for guidance or localization.",
    "The reasoning states a target value or plan without relating it to a location, record, or feature visible in the observation.",
    "The reasoning does not identify any target locus, next investigative step, or criterion adjustment from the observation."
  ]
}

